  }
  var g=grupos[diaTab]; var card=document.createElement('div'); card.className='card';
  card.innerHTML='<div class="prof">'+esc(diaTab)+'</div><div class="tablewrap"><table><thead><tr><th>Hora</th><th>Paciente</th><th>Atenção</th><th>Pacote / mensalidade</th><th>Origem</th><th>Situação</th></tr></thead><tbody>'+g.map(function(it,i){ return '<tr data-i="'+i+'" class="'+(it.registro?'done':'')+'" style="cursor:pointer"><td>'+esc(it.hora||'—')+'</td><td><b>'+esc(it.paciente)+'</b></td><td>'+esc(atencaoDe(it.paciente))+'</td><td>'+pillsDe(it.paciente)+'</td><td>'+esc(it.origem||'')+'</td><td>'+statusDe(it)+'</td></tr>'; }).join('')+'</tbody></table></div>';
  card.querySelectorAll('tr[data-i]').forEach(function(tr){ tr.addEventListener('click',function(){ selecionarItem(g[+tr.dataset.i]); }); });
  root.appendChild(card);
}
function selecionarItem(it){
  diaSel=it; $("#d-acao").hidden=false; $("#d-naovem").hidden=true; $("#d-remarcar").hidden=true;
  $("#d-acao-t").textContent=it.paciente+' · '+it.profissional+(it.hora?' · '+it.hora:'')+(it.registro?' · já registrado: '+it.registro.oque:'');
  $("#d-ac-reg").textContent = it.registro ? 'Registrar outro atendimento' : 'Registrar atendimento';
  $("#d-acao").scrollIntoView({behavior:'smooth',block:'center'});
}
$("#d-ac-fechar").addEventListener('click',function(){ $("#d-acao").hidden=true; });
$("#d-ac-reg").addEventListener('click',function(){ if(!diaSel) return; go('atendimento'); var it=diaSel; var fill=function(){ $("#a-pac").value=it.paciente; $("#a-prof").value=it.profissional; $("#a-data").value=DIA.data; if(it.hora) $("#a-hora").value=it.hora; onPacAt(true); fillTipos(); aplicarTipo(); }; if(AT&&!$("#f-atend").hidden) fill(); else { var t=setInterval(function(){ if(AT&&!$("#f-atend").hidden){ clearInterval(t); fill(); } },200); } });
$("#d-ac-naovem").addEventListener('click',function(){ $("#d-naovem").hidden=!$("#d-naovem").hidden; $("#d-remarcar").hidden=true; });
$("#d-ac-remarcar").addEventListener('click',function(){ $("#d-remarcar").hidden=!$("#d-remarcar").hidden; $("#d-naovem").hidden=true; });
$("#d-nv-ok").addEventListener('click',function(){
  if(!diaSel) return; var it=diaSel, p=pacInfo(it.paciente), esps=espsDoProf(it.profissional), base=tiposDe(esps)[0];
  var d={ paciente:it.paciente, profissional:it.profissional, data:DIA.data, hora:it.hora||'', procedimento: base?derivarProc(base.nome,p||{}):'', oque:$("#d-nv-motivo").value, pago:'', valor:'', forma:'', dataPagamento:'', quemPagou:'', nf:'Não se aplica', nfNumero:'', guia:'', observacao:$("#d-nv-obs").value.trim(), pacoteId:'', sessaoExtra:false, tornarPagadorHabitual:false };
  var pk=p&&AT.pacotes[p.nome]; if(p&&ehPacote(p)&&pk&&pk.status==='ativo'&&/sem aviso|em cima da hora/.test(d.oque)) d.pacoteId=pk.id;
  $("#d-nv-ok").disabled=true;
  call('registrarAtendimento', d).then(function(r){ if(!r.ok) return toast((r.erros||['Não gravou']).join(' ')); toast('Gravado: '+d.oque); $("#d-nv-obs").value=''; carregarDia(); }).catch(function(e){ toast('Erro: '+e.message); }).finally(function(){ $("#d-nv-ok").disabled=false; });
});
$("#d-rm-ok").addEventListener('click',function(){
  if(!diaSel) return; var para=$("#d-rm-data").value; if(!dataObj(para)) return toast('Informe a nova data (dd/mm/aaaa)');
  var d={ de:DIA.data, para:para, horaDe:diaSel.hora||'', horaPara:$("#d-rm-hora").value||diaSel.hora||'', paciente:diaSel.paciente, profissional:diaSel.profissional, observacao:$("#d-rm-obs").value.trim() };
  $("#d-rm-ok").disabled=true;
  call('remarcar', d).then(function(r){ if(!r.ok) return toast((r.erros||['Não gravou']).join(' ')); toast('Remarcado para '+para); $("#d-rm-data").value=''; $("#d-rm-hora").value=''; $("#d-rm-obs").value=''; carregarDia(); }).catch(function(e){ toast('Erro: '+e.message); }).finally(function(){ $("#d-rm-ok").disabled=false; });
});
$("#d-rm-data").addEventListener('input',function(){ this.value=mascaraData(this.value); });
$("#d-rm-hora").addEventListener('input',function(){ var v=this.value.replace(/\D/g,'').slice(0,4); this.value=v.length>2?v.slice(0,2)+':'+v.slice(2):v; });
$("#d-hoje").addEventListener('click',function(){ $("#d-data").value=hojeStr(); carregarDia(); });
$("#d-data").addEventListener('input',function(){ this.value=mascaraData(this.value); });
$("#d-data").addEventListener('change',function(){ if(dataObj(this.value)) carregarDia(); });
$("#d-print").addEventListener('click',function(){ window.print(); });
$("#d-add").addEventListener('click',function(){ $("#d-addbox").hidden=!$("#d-addbox").hidden; $("#d-recbox").hidden=true; });
$("#d-add-cancel").addEventListener('click',function(){ $("#d-addbox").hidden=true; });
$("#d-add-hora").addEventListener('input',function(){ var v=this.value.replace(/\D/g,'').slice(0,4); this.value=v.length>2?v.slice(0,2)+':'+v.slice(2):v; });
function addDia(recorrente){
  var pac=$("#d-add-pac").value.trim(), prof=$("#d-add-prof").value, hora=$("#d-add-hora").value;
  if(!pacInfo(pac)) return toast('Escolha um paciente da lista');
  var fn = recorrente ? call('salvarAgendaFixa',{paciente:pac,profissional:prof,diaSemana:DIAS_PT[dataObj(DIA.data).getDay()],hora:hora,frequencia:'Semanal',comecaEm:DIA.data,ativo:true,observacao:$("#d-add-obs").value.trim()}) : call('acrescentarAoDia',{data:DIA.data,hora:hora,paciente:pac,profissional:prof,origem:$("#d-add-origem").value,observacao:$("#d-add-obs").value.trim()});
  fn.then(function(r){ if(!r.ok) return toast((r.erros||['Não gravou']).join(' ')); toast(recorrente?'Recorrência criada':'Agendado no dia'); $("#d-add-pac").value=''; $("#d-add-hora").value=''; $("#d-add-obs").value=''; $("#d-addbox").hidden=true; carregarDia(); }).catch(function(e){ toast('Erro: '+e.message); });
}
$("#d-add-ok").addEventListener('click',function(){ addDia(false); });
$("#d-add-rec").addEventListener('click',function(){ addDia(true); });
/* agenda recorrente */
function carregarRec(){ call('agendaFixa').then(function(l){ AGENDA=l; renderRec(); }); }
function renderRec(){
  var tb=$("#r-lista"); tb.innerHTML='';
  AGENDA.slice().sort(function(a,b){ return (DIAS_PT.indexOf(a['Dia da semana'])*10000+(a['Hora']||'').replace(':','')*1)-(DIAS_PT.indexOf(b['Dia da semana'])*10000+(b['Hora']||'').replace(':','')*1); }).forEach(function(a){
    var tr=document.createElement('tr'); tr.innerHTML='<td><b>'+esc(a['Paciente'])+'</b></td><td>'+esc(a['Profissional'])+'</td><td>'+esc(a['Dia da semana'])+'</td><td>'+esc(a['Hora'])+'</td><td>'+esc(a['Frequência']||'Semanal')+'</td><td>'+esc((a['Começa em']||'…')+' → '+(a['Termina em']||'…'))+'</td><td>'+(String(a['Ativo'])==='Não'?'<span class="pill muted">pausado</span>':'<span class="pill ok">ativo</span>')+'</td><td><button class="btn secondary small" type="button">Editar</button></td>';
    tr.querySelector('button').addEventListener('click',function(){ recEdit=a; $("#r-pac").value=a['Paciente']; $("#r-prof").value=a['Profissional']; $("#r-dia").value=a['Dia da semana']; $("#r-hora").value=a['Hora']; $("#r-freq").value=a['Frequência']||'Semanal'; $("#r-ini").value=a['Começa em']||''; $("#r-fim").value=a['Termina em']||''; $("#r-ativo").value=String(a['Ativo'])==='Não'?'Não':'Sim'; $("#r-obs").value=a['Observação']||''; $("#r-hint").textContent='Editando '+a['Paciente']+'. Mudou dia, hora ou profissional? Ao salvar, o app pergunta se vale a partir de hoje.'; $("#d-recbox").scrollIntoView({behavior:'smooth',block:'start'}); });
    tb.appendChild(tr);
  });
}
function limparRec(){ recEdit=null; ['r-pac','r-hora','r-ini','r-fim','r-obs'].forEach(function(id){ $("#"+id).value=''; }); $("#r-freq").value='Semanal'; $("#r-ativo").value='Sim'; $("#r-hint").textContent='Nova recorrência.'; }
$("#d-rec").addEventListener('click',function(){ $("#d-recbox").hidden=!$("#d-recbox").hidden; $("#d-addbox").hidden=true; if(!$("#d-recbox").hidden) carregarRec(); });
$("#d-rec-fechar").addEventListener('click',function(){ $("#d-recbox").hidden=true; });
$("#r-novo").addEventListener('click',limparRec);
$("#r-hora").addEventListener('input',function(){ var v=this.value.replace(/\D/g,'').slice(0,4); this.value=v.length>2?v.slice(0,2)+':'+v.slice(2):v; });
$("#r-ini").addEventListener('input',function(){ this.value=mascaraData(this.value); });
$("#r-fim").addEventListener('input',function(){ this.value=mascaraData(this.value); });
$("#r-salvar").addEventListener('click',function(){
  var pac=$("#r-pac").value.trim(); if(!pacInfo(pac)) return toast('Escolha um paciente da lista');
  var d={ id:recEdit?recEdit.ID:'', paciente:pac, profissional:$("#r-prof").value, diaSeman

a:$("#r-dia").value, hora:$("#r-hora").value, frequencia:$("#r-freq").value, comecaEm:$("#r-ini").value, terminaEm:$("#r-fim").value, ativo:$("#r-ativo").value==='Sim', observacao:$("#r-obs").value.trim() };
  if(recEdit && (recEdit['Dia da semana']!==d.diaSemana || recEdit['Hora']!==d.hora || recEdit['Profissional']!==d.profissional)){
    if(!$("#r-apartir")){ $("#r-hint").innerHTML='Dia, hora ou profissional mudou. <label class="inline" style="display:inline-flex"><input type="checkbox" id="r-apartir" checked> vale a partir de hoje (encerra a antiga e guarda o histórico)</label> <button class="btn small" type="button" id="r-confirma">Confirmar</button>'; $("#r-confirma").addEventListener('click',function(){ d.encerrarAnterior=$("#r-apartir").checked; salvarRec(d); }); return; }
    d.encerrarAnterior=$("#r-apartir").checked;
  }
  salvarRec(d);
});
function salvarRec(d){ $("#r-salvar").disabled=true; call('salvarAgendaFixa', d).then(function(r){ if(!r.ok) return toast((r.erros||['Não gravou']).join(' ')); toast('Recorrência salva'); limparRec(); carregarRec(); carregarDia(); }).catch(function(e){ toast('Erro: '+e.message); }).finally(function(){ $("#r-salvar").disabled=false; }); }
// ao limpar o atendimento, fecha a lista completa de procedimentos
var _limparAtOrig=limparAt; limparAt=function(a){ _limparAtOrig(a); $("#a-proc").hidden=true; };

carregar();
})();
</script>
</body>
</html>
